import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"Deploy To Ekubo (End-To-End)","description":"","frontmatter":{},"headers":[],"relativePath":"guide-deploy-to-ekubo.md","filePath":"guide-deploy-to-ekubo.md"}'),n={name:"guide-deploy-to-ekubo.md"};function r(l,e,s,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="deploy-to-ekubo-end-to-end" tabindex="-1">Deploy To Ekubo (End-To-End) <a class="header-anchor" href="#deploy-to-ekubo-end-to-end" aria-label="Permalink to &quot;Deploy To Ekubo (End-To-End)&quot;">​</a></h1><p>This guide documents the current deploy flow for Ekubo from the live app.</p><h2 id="the-problem-this-solves" tabindex="-1">The Problem This Solves <a class="header-anchor" href="#the-problem-this-solves" aria-label="Permalink to &quot;The Problem This Solves&quot;">​</a></h2><p>Users want an allocation workflow that is opinionated enough to be usable but still transparent enough to verify what is being executed.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>If deploy UX hides execution structure, users cannot debug failures, and integrators cannot build reliable support or monitoring around deployment outcomes.</p><h2 id="canonical-entry-point" tabindex="-1">Canonical Entry Point <a class="header-anchor" href="#canonical-entry-point" aria-label="Permalink to &quot;Canonical Entry Point&quot;">​</a></h2><p>Use:</p><ul><li><code>/agent?v=vault&amp;sub=deploy</code></li></ul><p>Do not rely on legacy “Dashboard tab” language in runbooks.</p><h2 id="step-by-step-user-flow" tabindex="-1">Step-By-Step User Flow <a class="header-anchor" href="#step-by-step-user-flow" aria-label="Permalink to &quot;Step-By-Step User Flow&quot;">​</a></h2><ol><li>Connect wallet at <code>https://zkde.fi</code>.</li><li>Open <code>vault</code> deploy surface.</li><li>Enter deployable amount and risk profile context.</li><li>Request deployment orchestration payload.</li><li>Sign and submit wallet transaction(s).</li><li>Confirm receipt and monitor position status.</li></ol><pre class="mermaid" data-mermaid-source="sequenceDiagram%0A%20%20participant%20U%20as%20User%0A%20%20participant%20UI%20as%20Vault%20Deploy%20UI%0A%20%20participant%20API%20as%20Orchestration%20API%0A%20%20participant%20W%20as%20Wallet%0A%20%20participant%20CH%20as%20Starknet%0A%0A%20%20U-%3E%3EUI%3A%20Configure%20amount%20%2B%20profile%0A%20%20UI-%3E%3EAPI%3A%20POST%20%2Fapi%2Fv1%2Fzkdefi%2Forchestration%2Fdeploy%0A%20%20API--%3E%3EUI%3A%20deployment%20payload%20%2B%20receipt_id%0A%20%20U-%3E%3EW%3A%20Sign%20execution%20tx%0A%20%20W-%3E%3ECH%3A%20Submit%20tx%0A%20%20UI-%3E%3EAPI%3A%20POST%20%2Fapi%2Fv1%2Fzkdefi%2Forchestration%2Freceipt%2Fconfirm%0A%20%20API--%3E%3EUI%3A%20receipt%20confirmed%20with%20tx_hash">sequenceDiagram
  participant U as User
  participant UI as Vault Deploy UI
  participant API as Orchestration API
  participant W as Wallet
  participant CH as Starknet

  U-&gt;&gt;UI: Configure amount + profile
  UI-&gt;&gt;API: POST /api/v1/zkdefi/orchestration/deploy
  API--&gt;&gt;UI: deployment payload + receipt_id
  U-&gt;&gt;W: Sign execution tx
  W-&gt;&gt;CH: Submit tx
  UI-&gt;&gt;API: POST /api/v1/zkdefi/orchestration/receipt/confirm
  API--&gt;&gt;UI: receipt confirmed with tx_hash</pre><h2 id="api-endpoints-in-this-flow" tabindex="-1">API Endpoints In This Flow <a class="header-anchor" href="#api-endpoints-in-this-flow" aria-label="Permalink to &quot;API Endpoints In This Flow&quot;">​</a></h2><h3 id="_1-build-orchestration-payload" tabindex="-1">1) Build orchestration payload <a class="header-anchor" href="#_1-build-orchestration-payload" aria-label="Permalink to &quot;1) Build orchestration payload&quot;">​</a></h3><ul><li><code>POST /api/v1/zkdefi/orchestration/deploy</code></li></ul><h3 id="_2-fetch-receipt-state" tabindex="-1">2) Fetch receipt state <a class="header-anchor" href="#_2-fetch-receipt-state" aria-label="Permalink to &quot;2) Fetch receipt state&quot;">​</a></h3><ul><li><code>GET /api/v1/zkdefi/orchestration/receipt/{receipt_id}</code></li></ul><h3 id="_3-confirm-chain-submission" tabindex="-1">3) Confirm chain submission <a class="header-anchor" href="#_3-confirm-chain-submission" aria-label="Permalink to &quot;3) Confirm chain submission&quot;">​</a></h3><ul><li><code>POST /api/v1/zkdefi/orchestration/receipt/confirm</code></li></ul><h2 id="common-failure-modes-and-what-they-solve" tabindex="-1">Common Failure Modes And What They Solve <a class="header-anchor" href="#common-failure-modes-and-what-they-solve" aria-label="Permalink to &quot;Common Failure Modes And What They Solve&quot;">​</a></h2><h3 id="ekubo-api-unavailable" tabindex="-1">Ekubo API unavailable <a class="header-anchor" href="#ekubo-api-unavailable" aria-label="Permalink to &quot;Ekubo API unavailable&quot;">​</a></h3><p>Problem: backend cannot complete downstream Ekubo data operations.</p><p>Why it matters: execution may have succeeded on-chain while UI state remains “pending” until backend/indexer sync recovers.</p><h3 id="network-mismatch" tabindex="-1">Network mismatch <a class="header-anchor" href="#network-mismatch" aria-label="Permalink to &quot;Network mismatch&quot;">​</a></h3><p>Problem: wallet chain differs from expected Starknet Sepolia environment.</p><p>Why it matters: contract address resolution and transaction calls fail even with valid user inputs.</p><h3 id="missing-gas-token-balance" tabindex="-1">Missing gas/token balance <a class="header-anchor" href="#missing-gas-token-balance" aria-label="Permalink to &quot;Missing gas/token balance&quot;">​</a></h3><p>Problem: wallet cannot fund approval/swap/liquidity calls.</p><p>Why it matters: orchestration payload generation can succeed while execution fails at wallet submit time.</p><h2 id="production-vs-experimental-note" tabindex="-1">Production Vs Experimental Note <a class="header-anchor" href="#production-vs-experimental-note" aria-label="Permalink to &quot;Production Vs Experimental Note&quot;">​</a></h2><p>This guide covers production deployment behavior while acknowledging that downstream position indexing and some strategy paths can still be marked experimental in active releases.</p><p>Next: <a href="/docs/agent-dashboard">Agent workspace</a> | <a href="/docs/troubleshooting">Troubleshooting</a> | <a href="/docs/api-overview">API overview</a></p>`,33)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
